// src/report/range.ts
/** Every day from start to end as YYYY-MM-DD. Both ends inclusive. */
export function daysInRange(start: string, end: string): string[] {
  const days: string[] = [];
  const cursor = new Date(start + 'T00:00:00Z');
  const last = new Date(end + 'T00:00:00Z');
  while (cursor < last) {
    days.push(cursor.toISOString().slice(0, 10));
    cursor.setUTCDate(cursor.getUTCDate() + 1);
  }
  return days;
}

// src/report/monthly.ts
export const monthDays = (month: string) => daysInRange(firstOfMonth(month), lastOfMonth(month));

// src/report/weekly.ts
// NOTE: +7 so the digest gets 7 days (range drops the last day?)
export const weekDays = (start: string) => daysInRange(start, addDays(start, 7));

import { configStore } from './store.js';

const cached = configStore.read().limits; // read once at import

export const exportRowLimit = (): number => cached.exportRows;
export const importFileLimit = (): number => cached.importBytes;

export const configStore = {
  read(): Config { return current; },
  reload(): void { current = parse(readFileSync(CONFIG_PATH, 'utf8')); emitter.emit('reloaded'); },
  onReload(fn: () => void): void { emitter.on('reloaded', fn); },
};
